import FeatureSectionV2 from "./feature-section-v2"

export default function Page() {
  return <FeatureSectionV2 />
}

import { features } from "../lib/features"
import WorkflowIllustration      from "./workflow-illustration"
import AnalyticsIllustration     from "./analytics-illustration"
import AccessControlIllustration from "./access-control-illustration"
import IntegrationsIllustration  from "./integrations-illustration"

export default function FeatureShowcase() {
  return (
    <ul className="fsv2-grid">
      {features.map(({ id, title, description }) => (
        <li key={id} className="fsv2-cell">
          <div className="fsv2-card">
            <div className="fsv2-card-top" aria-hidden="true">
              {id === "workflow-automation" && <WorkflowIllustration      />}
              {id === "real-time-analytics" && <AnalyticsIllustration     />}
              {id === "access-control"      && <AccessControlIllustration />}
              {id === "integrations"        && <IntegrationsIllustration  />}
            </div>
            <div className="fsv2-card-footer">
              <p className="fsv2-card-title">{title}</p>
              <p className="fsv2-card-desc">{description}</p>
            </div>
          </div>
        </li>
      ))}
    </ul>
  )
}

export type Feature = {
  id: string
  title: string
  description: string
}

export const features: Feature[] = [
  {
    id: "workflow-automation",
    title: "Workflow automation",
    description:
      "Set it up once and let it run. Your team gets back the time that used to disappear into repetitive work.",
  },
  {
    id: "real-time-analytics",
    title: "Real-time analytics",
    description:
      "Pull live data into your dashboards so you can act on it while it still matters, not days later when the weekly export finally lands.",
  },
  {
    id: "access-control",
    title: "Access control",
    description:
      "Give people exactly the access they need, keep sensitive areas locked down, and put an end to the permission requests piling up in your inbox.",
  },
  {
    id: "integrations",
    title: "Integrations",
    description:
      "Connect the tools your team already uses in minutes, without turning it into another engineering project.",
  },
]

/* feature-section-v2 */

.fsv2-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

@media (min-width: 640px) {
  .fsv2-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.fsv2-cell {
  min-width: 0;
}

/* ── Card ── */

.fsv2-card {
  position: relative;
  /* Fixed preview height — real-time analytics card is the reference for all four */
  --fsv2-illustration-height: 12rem;
  min-height: 17rem;
  background-color: color-mix(in oklab, var(--muted) 82%, var(--background) 18%);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
}

@media (max-width: 639px) {
  .fsv2-card {
    --fsv2-illustration-height: 10.5rem;
  }
}

.fsv2-card-top {
  flex: 0 0 var(--fsv2-illustration-height);
  height: var(--fsv2-illustration-height);
  min-height: var(--fsv2-illustration-height);
  max-height: var(--fsv2-illustration-height);
  display: flex;
  flex-direction: column;
}

/* Illustration fills the preview pane edge-to-edge and uses available height */
.fsv2-card-top > * {
  flex: 1 1 0%;
  min-height: 0;
  min-width: 0;
  align-self: stretch;
  width: 100%;
}

.fsv2-card-footer {
  margin-top: auto;
  padding: 1rem 1.1rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.fsv2-card-title {
  margin: 0;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  line-height: 1.35;
  text-transform: uppercase;
  color: color-mix(in oklab, var(--foreground) 88%, transparent);
}

.fsv2-card-desc {
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: var(--muted-foreground);
  /* Keeps card footers aligned when copy wraps across breakpoints */
  min-height: calc(0.8125rem * 1.55 * 3);
}

"use client"

import { Fragment } from "react"
import { cn } from "@/lib/utils"

import { useFsv2IllustrationActive }   from "../hooks/use-fsv2-illustration-active"
import { useWorkflowAnimation, STEPS } from "../hooks/use-workflow-animation"
import "../styles/workflow-illustration.css"

function CheckIcon() {
  return (
    <svg width="10" height="9" viewBox="0 0 8 7" fill="none" aria-hidden>
      <path
        d="M1 3.5L3 5.5L7 1"
        stroke="#052e16"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

export default function WorkflowIllustration() {
  const { ref, active }  = useFsv2IllustrationActive()
  const { statuses }     = useWorkflowAnimation(active)

  return (
    <div ref={ref} className="wfi-root">
      <div className="wfi-window">

        {/* ── Horizontal pipeline ── */}
        <div className="wfi-pipeline">
          <div className="wfi-row">
            {STEPS.map((step, i) => {
              const status    = statuses[i]!
              const isRunning = status === "running"
              const isDone    = status === "done"
              const isLast    = i === STEPS.length - 1

              return (
                <Fragment key={step.id}>

                  {/* Step: icon + label centered */}
                  <div className="wfi-step-col">
                    <div className={cn("wfi-icon", `wfi-icon--${status}`)}>
                      {isDone && <CheckIcon />}
                    </div>
                    <span className={cn(
                      "wfi-step-name",
                      isRunning && "wfi-step-name--running",
                      isDone    && "wfi-step-name--done",
                    )}>
                      {step.label}
                    </span>
                    <span className={cn(
                      "wfi-step-time",
                      !isDone && "wfi-step-time--hidden",
                    )}>
                      {step.badge}
                    </span>
                  </div>

                  {/* Connector between steps — outside the column */}
                  {!isLast && (
                    <div className={cn("wfi-h-connector", isDone && "wfi-h-connector--done")} />
                  )}

                </Fragment>
              )
            })}
          </div>
        </div>

      </div>
    </div>
  )
}

"use client"

import { cn } from "@/lib/utils"

import { useFsv2IllustrationActive } from "../hooks/use-fsv2-illustration-active"
import { useAnalyticsAnimation }     from "../hooks/use-analytics-animation"
import "../styles/analytics-illustration.css"

/* ── SVG chart path builder — straight lines for stock-chart feel ─────────── */

function buildChart(data: number[], W = 240, H = 60) {
  const PAD_T = 8
  const PAD_B = 0
  const n = data.length

  const min = Math.min(...data) * 0.88
  const max = Math.max(...data) * 1.04
  const range = max - min || 1

  const px = (i: number) => (i / (n - 1)) * W
  const py = (v: number) => PAD_T + (1 - (v - min) / range) * (H - PAD_T - PAD_B)

  // Straight segments — stock chart look
  let line = `M ${px(0).toFixed(2)} ${py(data[0]!).toFixed(2)}`
  for (let i = 1; i < n; i++) {
    line += ` L ${px(i).toFixed(2)} ${py(data[i]!).toFixed(2)}`
  }

  const sum = data.reduce((acc, v) => acc + v, 0)
  const avg = sum / n

  const lx = px(n - 1)
  const yLatest = py(data[n - 1]!)
  const yAverage = py(avg)
  const area = `${line} L ${lx.toFixed(2)} ${H + 2} L 0 ${H + 2} Z`

  // Grid Y positions at 25 / 50 / 75 % of chart area
  const gridYs = [0.25, 0.5, 0.75].map(t => PAD_T + t * (H - PAD_T - PAD_B))

  return { line, area, lx, yLatest, yAverage, gridYs }
}

/* ── Component ───────────────────────────────────────────────────────────── */

const W = 240
const H = 60

export default function AnalyticsIllustration() {
  const { ref, active } = useFsv2IllustrationActive()
  const { chartData, users, events, flashUser, trend } = useAnalyticsAnimation(active)

  const { line, area, lx, yLatest, yAverage, gridYs } = buildChart(chartData, W, H)

  const isUp   = trend === "up"
  const color  = isUp ? "#4ade80" : "#ef4444"
  const colorA = isUp ? "rgba(74,222,128," : "rgba(239,68,68,"

  return (
    <div ref={ref} className="ana-root">
      <div className="ana-window">

        {/* ── Primary metric ── */}
        <div className="ana-metric-section">
          <div className="ana-metric-left">
            <span className="ana-metric-label">Active Users</span>
            <span className={cn("ana-metric-value", flashUser && "ana-metric-value--flash")}>
              {users}
            </span>
          </div>
          <div className="ana-metric-right">
            <span className="ana-period-label">live</span>
          </div>
        </div>

        {/* ── Chart ── */}
        <div className="ana-chart">
          <svg
            className="ana-chart-svg"
            viewBox={`0 0 ${W} ${H}`}
            preserveAspectRatio="none"
            xmlns="http://www.w3.org/2000/svg"
            aria-hidden
          >
            <defs>
              <linearGradient id="ana-grad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%"   stopColor={`${colorA}0.18)`} />
                <stop offset="100%" stopColor={`${colorA}0.00)`} />
              </linearGradient>
            </defs>

            {/* Horizontal grid lines */}
            {gridYs.map((y, i) => (
              <line key={i} x1="0" y1={y} x2={W} y2={y}
                stroke="rgba(255,255,255,0.04)" strokeWidth="0.5" />
            ))}

            {/* Window average — reference line (live count is the dot) */}
            <line x1="0" y1={yAverage} x2={W} y2={yAverage}
              stroke="rgba(161,161,170,0.38)" strokeWidth="0.65"
              strokeDasharray="3 3.5" />

            {/* Area fill + line */}
            <path d={area} fill="url(#ana-grad)" />
            <path d={line} fill="none" stroke={color} strokeWidth="1.2" strokeLinejoin="round" />

            {/* Live endpoint */}
            <circle cx={lx} cy={yLatest} r="5" fill="none"
              stroke={`${colorA}0.35)`} strokeWidth="1.5"
              style={{ animation: "ana-ring-pulse 1.8s ease-out infinite" }} />
            <circle cx={lx} cy={yLatest} r="2" fill={color} />
          </svg>
        </div>

        {/* ── Secondary stats ── */}
        <div className="ana-stats">
          <div className="ana-stat">
            <span className="ana-stat-value">{events}</span>
            <span className="ana-stat-label">events / min</span>
          </div>
          <div className="ana-stat">
            <span className="ana-stat-value">99.4%</span>
            <span className="ana-stat-label">uptime</span>
          </div>
          <div className="ana-stat">
            <span className="ana-stat-value">142ms</span>
            <span className="ana-stat-label">latency</span>
          </div>
        </div>

      </div>
    </div>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"
import { cn } from "@/lib/utils"

import { useFsv2IllustrationActive }     from "../hooks/use-fsv2-illustration-active"
import { useAccessAnimation, ROLE_META } from "../hooks/use-access-animation"
import type { Role }                     from "../hooks/use-access-animation"
import "../styles/access-control-illustration.css"

const ROLE_BAR: Record<Role, string> = {
  admin:  "100%",
  editor: "75%",
  mod:    "55%",
  member: "35%",
  viewer: "0%",
}

const ROLE_LEVEL: Record<Role, string> = {
  admin:  "4/4",
  editor: "3/4",
  mod:    "2/4",
  member: "1/4",
  viewer: "0/4",
}

function CursorSvg() {
  return (
    <svg width="11" height="13" viewBox="0 0 11 13" fill="none" aria-hidden>
      <path
        d="M1.5 1 L1.5 10.5 L4 7.8 L6.1 12 L7.6 11.3 L5.5 7.1 L9 7.1 Z"
        fill="white"
        stroke="rgba(0,0,0,0.5)"
        strokeWidth="0.9"
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </svg>
  )
}

export default function AccessControlIllustration() {
  const { ref: rootRef, active }                           = useFsv2IllustrationActive()
  const { users, roles, flashIdx, cursorTarget, cursorPhase } = useAccessAnimation(active)

  // Refs for each row's role pill
  const pillRefs  = useRef<Array<HTMLSpanElement | null>>([])
  const windowRef = useRef<HTMLDivElement>(null)

  // Cursor position in px relative to .acl-window top-left
  const [cursorPos, setCursorPos] = useState<{ x: number; y: number } | null>(null)

  // Re-position cursor whenever the target changes
  useEffect(() => {
    if (cursorTarget === null || !windowRef.current) return
    const pill = pillRefs.current[cursorTarget]
    if (!pill) return

    const winRect  = windowRef.current.getBoundingClientRect()
    const pillRect = pill.getBoundingClientRect()

    // Offset by the SVG tip coords (1.5, 1) so the arrow point lands at pill center
    setCursorPos({
      x: pillRect.left - winRect.left + pillRect.width  * 0.5 - 1.5,
      y: pillRect.top  - winRect.top  + pillRect.height * 0.5 - 1,
    })
  }, [cursorTarget])

  // Seed initial cursor position at Sarah's pill on mount
  useEffect(() => {
    if (!windowRef.current) return
    const pill = pillRefs.current[0]
    if (!pill) return

    const winRect  = windowRef.current.getBoundingClientRect()
    const pillRect = pill.getBoundingClientRect()

    // Offset by the SVG tip coords (1.5, 1) so the arrow point lands at pill center
    setCursorPos({
      x: pillRect.left - winRect.left + pillRect.width  * 0.5 - 1.5,
      y: pillRect.top  - winRect.top  + pillRect.height * 0.5 - 1,
    })
  }, [])

  const isHovering = (i: number) =>
    cursorTarget === i && (cursorPhase === "hover" || cursorPhase === "click")

  const cursorVisible = cursorPhase !== "idle"

  return (
    <div ref={rootRef} className="acl-root">
      <div ref={windowRef} className="acl-window">

        {/* ── Member table ── */}
        <div className="acl-table">
          <div className="acl-thead" aria-hidden>
            <span className="acl-th acl-th--member">Member</span>
            <span className="acl-th acl-th--role">Role</span>
            <span className="acl-th acl-th--access">Access</span>
            <span className="acl-th acl-th--level">Level</span>
          </div>
          <div className="acl-rows">
            {users.map((user, i) => {
              const role = roles[i]!
              return (
                <div
                  key={user.initials}
                  className={cn("acl-tr", flashIdx === i && "acl-tr--flash")}
                >
                  <span className="acl-name">{user.name}</span>
                  <span
                    ref={el => { pillRefs.current[i] = el }}
                    className={cn(
                      "acl-role-pill",
                      `acl-role-pill--${role}`,
                      isHovering(i) && "acl-role-pill--cursor-hover",
                    )}
                  >
                    {ROLE_META[role].label}
                  </span>
                  <div className="acl-bar-wrap" aria-hidden>
                    <div
                      className={cn("acl-bar-fill", `acl-bar-fill--${role}`)}
                      style={{ width: ROLE_BAR[role] }}
                    />
                  </div>
                  <span className={cn("acl-level", `acl-level--${role}`)}>
                    {ROLE_LEVEL[role]}
                  </span>
                </div>
              )
            })}
          </div>
        </div>

        {/* ── Cursor ── */}
        {cursorPos && (
          <div
            className={cn(
              "acl-cursor",
              !cursorVisible      && "acl-cursor--hidden",
              cursorPhase === "click" && "acl-cursor--clicking",
            )}
            style={{ transform: `translate(${cursorPos.x}px, ${cursorPos.y}px)` }}
            aria-hidden
          >
            <div className={cn(
              "acl-cursor-icon",
              cursorPhase === "click" && "acl-cursor-icon--click",
            )}>
              <CursorSvg />
            </div>
          </div>
        )}

      </div>
    </div>
  )
}

"use client"

import type { SVGProps } from "react"
import { useId } from "react"
import { cn } from "@/lib/utils"

import { GithubDark } from "@/components/ui/svgs/githubDark"
import { VercelDark } from "@/components/ui/svgs/vercelDark"
import { Supabase }   from "@/components/ui/svgs/supabase"
import { OpenaiDark } from "@/components/ui/svgs/openaiDark"

import type { SyncStatus } from "../hooks/use-integrations-animation"
import { useFsv2IllustrationActive }  from "../hooks/use-fsv2-illustration-active"
import { useIntegrationsAnimation }   from "../hooks/use-integrations-animation"
import "../styles/integrations-illustration.css"

/* ── Icon registry ───────────────────────────────────────────────────────── */

type IconComp = React.ComponentType<SVGProps<SVGSVGElement>>

const ICON_MAP: Record<string, IconComp> = {
  github:   GithubDark,
  vercel:   VercelDark,
  supabase: Supabase,
  openai:   OpenaiDark,
}

/** Stroke / fill accent per brand */
const CHART_ACCENT: Record<string, string> = {
  github:   "#39d353",
  vercel:   "#e4e4e7",
  supabase: "#3ecf8e",
  openai:   "#74aa9c",
}

/* ── Metric formatter ────────────────────────────────────────────────────── */

function fmtMetric(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`
  return `${n}`
}

function statusLabel(s: SyncStatus): string {
  return s === "syncing" ? "Syncing" : "Connected"
}

/** Map the last N absolute readings into 0–100 for the SVG (shape = recent relative range) */
function normalizeMetricWindow(values: number[]): number[] {
  const min = Math.min(...values)
  const max = Math.max(...values)
  if (max === min) return values.map(() => 50)
  return values.map((v) => ((v - min) / (max - min)) * 100)
}

/* ── SVG area + line chart ───────────────────────────────────────────────── */

function IntegrationChart({
  integrationId,
  values,
}: {
  integrationId: string
  values:        number[]
}) {
  const rawId  = useId()
  const gradId = `itg-chart-grad-${rawId.replace(/:/g, "")}`
  const accent = CHART_ACCENT[integrationId] ?? "#71717a"
  const n      = values.length
  const padX   = 1.5
  const padY   = 2.5
  const w      = 100
  const h      = 34
  const bottom = h - padY
  const spanX  = w - 2 * padX
  const spanY  = bottom - padY

  const pts = values.map((v, i) => {
    const x = n <= 1 ? padX + spanX / 2 : padX + (i / (n - 1)) * spanX
    const y = bottom - (v / 100) * spanY
    return [x, y] as const
  })

  const lineD =
    pts.map((p, i) => `${i === 0 ? "M" : "L"} ${p[0]},${p[1]}`).join(" ")
  const areaD =
    `M ${pts[0]![0]},${bottom} ` +
    pts.map((p) => `L ${p[0]},${p[1]}`).join(" ") +
    ` L ${pts[n - 1]![0]},${bottom} Z`

  return (
    <div className="itg-chart-wrap">
      <svg
        className="itg-chart"
        viewBox={`0 0 ${w} ${h}`}
        preserveAspectRatio="none"
        aria-hidden
      >
        <defs>
          <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={accent} stopOpacity="0.5" />
            <stop offset="100%" stopColor={accent} stopOpacity="0" />
          </linearGradient>
        </defs>
        <line
          className="itg-chart-baseline"
          x1={padX}
          y1={bottom}
          x2={w - padX}
          y2={bottom}
        />
        <path className="itg-chart-area" d={areaD} fill={`url(#${gradId})`} />
        <path
          className="itg-chart-line"
          d={lineD}
          fill="none"
          stroke={accent}
        />
      </svg>
    </div>
  )
}

/* ── Component ───────────────────────────────────────────────────────────── */

export default function IntegrationsIllustration() {
  const { ref, active } = useFsv2IllustrationActive()
  const { integrations, metrics, metricHistory, statuses, flashIdx } =
    useIntegrationsAnimation(active)

  return (
    <div ref={ref} className="itg-root">
      <div className="itg-window">
        <div className="itg-header" aria-hidden>
          <span className="itg-header-skip" />
          <span className="itg-header-label itg-header-label--source">Source</span>
          <span className="itg-header-label itg-header-label--metric">Metric</span>
          <span className="itg-header-label itg-header-label--window">Window</span>
          <span className="itg-header-label itg-header-label--value">Value</span>
          <span className="itg-header-label itg-header-label--status" />
        </div>

        <div className="itg-rows" role="list">
            {integrations.map((app, i) => {
              const Icon    = ICON_MAP[app.id]!
              const status  = statuses[i]!
              const syncing = status === "syncing"
              const flash   = flashIdx === i
              const value   = metrics[i]!
              const chart   = normalizeMetricWindow(metricHistory[i]!)

              return (
                <div
                  key={app.id}
                  role="listitem"
                  className={cn("itg-row", flash && "itg-row--flash")}
                  aria-label={`${app.name}, ${fmtMetric(value)} ${app.metric}, ${statusLabel(status)}. Sample window trend shown visually.`}
                >
                  <span className="itg-logo" aria-hidden>
                    <Icon className="itg-logo-svg" />
                  </span>

                  <span className="itg-name">{app.name}</span>

                  <span className="itg-col-label">{app.metric}</span>

                  <IntegrationChart
                    integrationId={app.id}
                    values={chart}
                  />

                  <span
                    className={cn(
                      "itg-metric",
                      flash &&
                        (syncing ? "itg-metric--flash-amber" : "itg-metric--flash-emerald"),
                    )}
                  >
                    {fmtMetric(value)}
                  </span>

                  <span className="itg-status" title={statusLabel(status)}>
                    <span
                      className={cn(
                        "itg-status-dot",
                        syncing ? "itg-status-dot--syncing" : "itg-status-dot--on",
                      )}
                      aria-hidden
                    />
                    <span className="itg-sr-only">{statusLabel(status)}</span>
                  </span>
                </div>
              )
            })}
        </div>
      </div>
    </div>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"

/** Pauses illustration timers when the panel is off-screen. */
export function useFsv2IllustrationActive() {
  const ref = useRef<HTMLDivElement>(null)
  const [active, setActive] = useState(true)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    const obs = new IntersectionObserver(
      ([e]) => setActive(!!e?.isIntersecting),
      { rootMargin: "48px", threshold: 0.12 },
    )
    obs.observe(el)
    return () => obs.disconnect()
  }, [])

  return { ref, active }
}

export function useFsv2ReducedMotion() {
  const [reduced, setReduced] = useState(false)

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    const sync = () => setReduced(mq.matches)
    sync()
    mq.addEventListener("change", sync)
    return () => mq.removeEventListener("change", sync)
  }, [])

  return reduced
}

"use client"

// Phase flow: idle → running (steps 0..N in sequence) → done → idle (loops)

import { useEffect, useState } from "react"

export type StepStatus = "pending" | "running" | "done"

export interface WorkflowStep {
  id:       string
  label:    string
  detail:   string
  badge:    string
  duration: number   // ms the step stays "running"
}

type Phase = "idle" | "running" | "done"

// ─────────────────────────────────────────────────────────────────────────────

export const STEPS: WorkflowStep[] = [
  { id: "signup",  label: "User Signed Up",  detail: "POST /hooks/auth/signup",      badge: "1ms",   duration: 850  },
  { id: "account", label: "Account Created", detail: "workspace provisioned",        badge: "38ms",  duration: 700  },
  { id: "email",   label: "Welcome Email",   detail: "via sendgrid  →  delivered",   badge: "94ms",  duration: 900  },
  { id: "slack",   label: "Slack Notified",  detail: "channel  #new-customers",      badge: "210ms", duration: 750  },
  { id: "trial",   label: "Trial Started",   detail: "14-day trial activated",       badge: "5ms",   duration: 650  },
]

const IDLE_MS = 900
const DONE_MS = 2600

// ─────────────────────────────────────────────────────────────────────────────

export function useWorkflowAnimation(active: boolean) {
  const [phase,    setPhase]    = useState<Phase>("idle")
  const [statuses, setStatuses] = useState<StepStatus[]>(STEPS.map(() => "pending"))
  const [current,  setCurrent]  = useState(-1)

  const allDone = phase === "done"

  // idle → start
  useEffect(() => {
    if (!active || phase !== "idle") return
    const t = setTimeout(() => {
      setStatuses(STEPS.map(() => "pending"))
      setCurrent(0)
      setPhase("running")
    }, IDLE_MS)
    return () => clearTimeout(t)
  }, [phase, active])

  // running: animate the current step, then advance
  useEffect(() => {
    if (!active || phase !== "running" || current < 0) return

    // Mark current step as running
    setStatuses((prev) => prev.map((s, i) => (i === current ? "running" : s)))

    const step = STEPS[current]!
    const t = setTimeout(() => {
      // Resolve step to done
      setStatuses((prev) => prev.map((s, i) => (i === current ? "done" : s)))

      if (current + 1 < STEPS.length) {
        setCurrent(current + 1)
      } else {
        setPhase("done")
        setCurrent(-1)
      }
    }, step.duration)

    return () => clearTimeout(t)
  }, [phase, current, active])

  // done → reset
  useEffect(() => {
    if (!active || phase !== "done") return
    const t = setTimeout(() => {
      setPhase("idle")
    }, DONE_MS)
    return () => clearTimeout(t)
  }, [phase, active])

  return { steps: STEPS, statuses, allDone }
}

"use client"

import { useEffect, useRef, useState } from "react"

/** Points on the line = active users in the window; headline = last point */
const SERIES_LEN = 22
const TICK_MS = 1000
const FLASH_MS = 400

/** ~50k band with room for visible swings */
const USER_MIN = 43_000
const USER_MAX = 58_000

function clamp(n: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, n))
}

function formatCount(n: number): string {
  return Math.round(n).toLocaleString("en-US")
}

/** Start mid-40s → low-50s so the first frame already shows movement */
function seedSeries(): number[] {
  const lo = 47_800
  const hi = 51_200
  return Array.from({ length: SERIES_LEN }, (_, i) =>
    Math.round(lo + ((hi - lo) * i) / (SERIES_LEN - 1)),
  )
}

function eventsPerMinuteFromUsers(activeUsers: number): number {
  return Math.round(clamp(activeUsers * 0.38, 14_200, 25_800))
}

// ─────────────────────────────────────────────────────────────────────────────

export function useAnalyticsAnimation(active: boolean) {
  const [series, setSeries] = useState(seedSeries)
  const [flashUser, setFlashUser] = useState(false)

  const prevLatestRef = useRef(series[series.length - 1]!)
  const flashTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

  const latest = series[series.length - 1]!
  const windowAvg =
    series.reduce((acc, v) => acc + v, 0) / series.length
  /** Green when live count is at/above the dashed window average, red when below */
  const trend: "up" | "down" = latest >= windowAvg ? "up" : "down"

  const users = formatCount(latest)
  const events = formatCount(eventsPerMinuteFromUsers(latest))

  useEffect(() => {
    if (!active) return

    const id = setInterval(() => {
      setSeries((prev) => {
        const last = prev[prev.length - 1]!
        // Steep slopes + frequent spikes (independent rolls so some ticks stack)
        let delta = Math.round(-1_050 + Math.random() * 2_100)
        if (Math.random() < 0.32) {
          delta += Math.round((Math.random() - 0.4) * 10_000)
        }
        if (Math.random() < 0.18) {
          delta += Math.round((Math.random() - 0.5) * 6_800)
        }
        if (Math.random() < 0.08) {
          delta += Math.round((Math.random() - 0.45) * 14_000)
        }
        const next = clamp(last + delta, USER_MIN, USER_MAX)
        return [...prev.slice(1), next]
      })
    }, TICK_MS)

    return () => clearInterval(id)
  }, [active])

  useEffect(() => {
    const l = series[series.length - 1]!
    if (l > prevLatestRef.current) {
      if (flashTimer.current) clearTimeout(flashTimer.current)
      setFlashUser(true)
      flashTimer.current = setTimeout(() => setFlashUser(false), FLASH_MS)
    }
    prevLatestRef.current = l
  }, [series])

  useEffect(
    () => () => {
      if (flashTimer.current) clearTimeout(flashTimer.current)
    },
    [],
  )

  return {
    chartData: series,
    users,
    events,
    flashUser,
    trend,
  }
}

"use client"

import { useEffect, useRef, useState } from "react"

export type Role        = "admin" | "editor" | "mod" | "member" | "viewer"
export type CursorPhase = "idle" | "approach" | "hover" | "click" | "pause"

export interface AclUser {
  initials:    string
  name:        string
  avatarColor: string
}

export const USERS: AclUser[] = [
  { initials: "JD", name: "John Doe",   avatarColor: "#7c3aed" },
  { initials: "JS", name: "Jane Smith", avatarColor: "#2563eb" },
  { initials: "BB", name: "Bob Brown",  avatarColor: "#d97706" },
  { initials: "AJ", name: "Alice Jones", avatarColor: "#0e7490" },
]

export const ROLE_META: Record<Role, { label: string; read: boolean; write: boolean; manage: boolean }> = {
  admin:  { label: "Admin",  read: true,  write: true,  manage: true  },
  editor: { label: "Editor", read: true,  write: true,  manage: false },
  mod:    { label: "Mod",    read: true,  write: true,  manage: false },
  member: { label: "Member", read: true,  write: false, manage: false },
  viewer: { label: "Viewer", read: true,  write: false, manage: false },
}

const SEQUENCE: [number, Role][] = [
  [1, "admin"],
  [2, "editor"],
  [3, "member"],
  [2, "mod"],
  [3, "viewer"],
  [1, "editor"],
  [3, "mod"],
  [2, "member"],
  [1, "mod"],
  [3, "editor"],
]

const INITIAL_ROLES: Role[] = ["admin", "editor", "member", "mod"]

const APPROACH_MS = 700
const HOVER_MS    = 420
const CLICK_MS    = 300
const PAUSE_MS    = 1600
const FLASH_MS    = 500

// ─────────────────────────────────────────────────────────────────────────────

export function useAccessAnimation(active: boolean) {
  const [roles,        setRoles]        = useState<Role[]>(INITIAL_ROLES)
  const [flashIdx,     setFlashIdx]     = useState<number | null>(null)
  const [cursorTarget, setCursorTarget] = useState<number | null>(null)
  const [cursorPhase,  setCursorPhase]  = useState<CursorPhase>("idle")

  const seqRef    = useRef(0)
  const timersRef = useRef<ReturnType<typeof setTimeout>[]>([])

  useEffect(() => {
    if (!active) return

    const push = (fn: () => void, ms: number) => {
      const t = setTimeout(fn, ms)
      timersRef.current.push(t)
    }

    function runNext() {
      const [userIdx, newRole] = SEQUENCE[seqRef.current % SEQUENCE.length]!
      seqRef.current++

      // 1. Approach — cursor starts moving toward target pill
      setCursorTarget(userIdx)
      setCursorPhase("approach")

      push(() => {
        // 2. Hover — cursor has arrived, lingering
        setCursorPhase("hover")

        push(() => {
          // 3. Click — role changes, flash fires
          setCursorPhase("click")
          setRoles(prev => prev.map((r, i) => (i === userIdx ? newRole : r)))
          setFlashIdx(userIdx)
          push(() => setFlashIdx(null), FLASH_MS)

          push(() => {
            // 4. Pause — cursor stays put before next action
            setCursorPhase("pause")
            push(runNext, PAUSE_MS)
          }, CLICK_MS)
        }, HOVER_MS)
      }, APPROACH_MS)
    }

    // Short initial delay before first action
    push(runNext, 800)

    return () => {
      timersRef.current.forEach(clearTimeout)
      timersRef.current = []
      setCursorPhase("idle")
      setCursorTarget(null)
    }
  }, [active])

  return { users: USERS, roles, flashIdx, cursorTarget, cursorPhase }
}

"use client"

import { useEffect, useReducer, useRef, useState } from "react"

export type SyncStatus = "connected" | "syncing"

export interface Integration {
  id:     string
  name:   string
  metric: string
  base:   number
}

export const INTEGRATIONS: Integration[] = [
  { id: "github",   name: "GitHub",   metric: "commits",   base: 847  },
  { id: "vercel",   name: "Vercel",   metric: "deploys",   base: 23   },
  { id: "supabase", name: "Supabase", metric: "queries",   base: 5200 },
  { id: "openai",   name: "OpenAI",   metric: "tokens",    base: 12400},
]

const HISTORY_LEN = 24

/** Seed a believable ramp into the current counter so the first frame is not flat */
function seedHistory(base: number): number[] {
  const spread = Math.max(6, Math.round(base * 0.035))
  const start  = Math.max(0, base - spread)
  return Array.from({ length: HISTORY_LEN }, (_, i) =>
    Math.round(start + ((base - start) * i) / (HISTORY_LEN - 1)),
  )
}

type MetricsState = {
  metrics:       number[]
  metricHistory: number[][]
}

function initialMetricsState(): MetricsState {
  return {
    metrics:       INTEGRATIONS.map((i) => i.base),
    metricHistory: INTEGRATIONS.map((i) => seedHistory(i.base)),
  }
}

function tickMetrics(state: MetricsState): MetricsState {
  const next = state.metrics.map((m, i) => {
    if (i === 0) return m + Math.floor(Math.random() * 3) + 1
    if (i === 1) return m + (Math.random() < 0.35 ? 1 : 0)
    if (i === 2) return m + Math.floor(Math.random() * 150) + 50
    if (i === 3) return m + Math.floor(Math.random() * 400) + 100
    return m
  })
  const metricHistory = state.metricHistory.map((row, i) => [...row.slice(1), next[i]!])
  return { metrics: next, metricHistory }
}

function metricsReducer(state: MetricsState, _action: "tick"): MetricsState {
  return tickMetrics(state)
}

const METRIC_INTERVAL_MS = 1600
const FLASH_MS = 550

/** Rotate through rows; each sync is a short pulse then idle before the next row */
const SYNC_ORDER = [2, 3, 0, 1] as const

// ─────────────────────────────────────────────────────────────────────────────

export function useIntegrationsAnimation(active: boolean) {
  const [{ metrics, metricHistory }, dispatchTick] = useReducer(
    metricsReducer,
    undefined,
    initialMetricsState,
  )

  const [statuses, setStatuses] = useState<SyncStatus[]>(() =>
    INTEGRATIONS.map(() => "connected"),
  )
  const [flashIdx, setFlashIdx] = useState<number | null>(null)

  const flashTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const turnRef = useRef(0)

  useEffect(() => {
    if (!active) return
    const t = setInterval(() => dispatchTick("tick"), METRIC_INTERVAL_MS)
    return () => clearInterval(t)
  }, [active])

  useEffect(() => {
    if (!active) return

    let cancelled = false
    const pending: ReturnType<typeof setTimeout>[] = []

    const clearPending = () => {
      for (const id of pending) clearTimeout(id)
      pending.length = 0
    }

    const scheduleSyncCycle = () => {
      if (cancelled) return

      const idx = SYNC_ORDER[turnRef.current % SYNC_ORDER.length]!
      turnRef.current++

      setStatuses((prev) => prev.map((_, i) => (i === idx ? "syncing" : "connected")))
      setFlashIdx(idx)
      if (flashTimerRef.current) clearTimeout(flashTimerRef.current)
      flashTimerRef.current = setTimeout(() => setFlashIdx(null), FLASH_MS)

      const pulseMs = 680 + Math.floor(Math.random() * 420)
      const gapMs   = 2000 + Math.floor(Math.random() * 1600)

      pending.push(
        setTimeout(() => {
          if (cancelled) return
          setStatuses((prev) => prev.map(() => "connected"))
        }, pulseMs),
      )

      pending.push(
        setTimeout(() => {
          if (cancelled) return
          clearPending()
          scheduleSyncCycle()
        }, pulseMs + gapMs),
      )
    }

    scheduleSyncCycle()

    return () => {
      cancelled = true
      clearPending()
      if (flashTimerRef.current) clearTimeout(flashTimerRef.current)
      flashTimerRef.current = null
    }
  }, [active])

  return { integrations: INTEGRATIONS, metrics, metricHistory, statuses, flashIdx }
}

