  flex: 1 1 0%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 0 1.25rem;
  min-height: 0;
}

/* ── Inner row: step cols interleaved with connectors ─────────────────────── */

.wfi-row {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
}

/* ── Step column — centered content, no flex stretch ─────────────────────── */

.wfi-step-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
  gap: 0.45rem;
}

/* ── Icon ─────────────────────────────────────────────────────────────────── */

.wfi-icon {
  width: 1.25rem;
  height: 1.25rem;
  border-radius: 9999px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-sizing: border-box;
}

.wfi-icon--pending {
  border: 1px solid rgba(255,255,255,0.12);
