  padding: 0.875rem 0.875rem 0.75rem;
}

.acl-window {
  position: relative;
  flex: 1 1 0%;
  min-height: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  background: #0a0a0a;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 0.5rem;
  overflow: hidden;
  box-shadow: 0 4px 32px rgba(0,0,0,0.8), 0 0 0 1px rgba(255,255,255,0.02) inset;
}

/* ── Member table (integrations-style shared grid) ────────────────────────── */

.acl-table {
  flex: 1 1 0%;
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 0.5rem 0.875rem 0;
}

.acl-thead,
.acl-tr {
  display: grid;
  align-items: center;
  column-gap: 0.5rem;
  grid-template-columns: minmax(0, 1fr) 2.75rem minmax(0, 1.5fr) 1.75rem;
}

.acl-thead {
  padding-bottom: 0.3rem;
  flex-shrink: 0;
}

.acl-th {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.4375rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #a1a1aa;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.acl-th--member  { justify-self: start;   text-align: left;  }
.acl-th--role    { justify-self: center;  text-align: center; }
.acl-th--access  { justify-self: stretch; }
.acl-th--level   { justify-self: end;     text-align: right; }

.acl-rows {
  flex: 1 1 0%;
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  padding-bottom: 0.25rem;
  min-height: 0;
}

.acl-tr {
  padding: 0.22rem 0;
}

.acl-tr--flash {
  animation: acl-row-flash 0.55s ease-out;
}

/* ── Member name ──────────────────────────────────────────────────────────── */

.acl-name {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.5625rem;
  font-weight: 500;
  color: #fafafa;
  white-space: nowrap;
  min-width: 0;
  justify-self: start;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1;
}

/* ── Role pill (centered column, like itg-col-label) ─────────────────────── */

.acl-role-pill {
  font-family: ui-monospace, monospace;
  font-size: 0.375rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.125rem 0.35rem;
  border-radius: 3px;
  border: 1px solid transparent;
  line-height: 1.2;
  justify-self: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: color 0.35s ease, border-color 0.35s ease, background 0.35s ease,
              box-shadow 0.15s ease;
}

.acl-role-pill--cursor-hover {
  box-shadow: 0 0 0 1.5px currentColor;
}

.acl-role-pill--admin {
  color: #4ade80;
  border-color: rgba(74,222,128,0.35);
  background: rgba(74,222,128,0.08);
}

.acl-role-pill--editor {
  color: #7dd3fc;
  border-color: rgba(125,211,252,0.35);
  background: rgba(125,211,252,0.08);
}

.acl-role-pill--mod {
  color: #c084fc;
  border-color: rgba(192,132,252,0.35);
  background: rgba(192,132,252,0.08);
}

.acl-role-pill--member {
  color: #a1a1aa;
  border-color: rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.04);
}

.acl-role-pill--viewer {
  color: #a1a1aa;
  border-color: rgba(113,113,122,0.25);
  background: transparent;
}

/* ── Permission bar (like itg-chart-wrap) ────────────────────────────────── */

.acl-bar-wrap {
  min-width: 0;
  width: 100%;
  height: 0.28rem;
  justify-self: stretch;
  align-self: center;
  background: rgba(255,255,255,0.06);
  border-radius: 9999px;
  overflow: hidden;
}

.acl-bar-fill {
  height: 100%;
  border-radius: 9999px;
  transition: width 0.45s cubic-bezier(0.4, 0, 0.2, 1),
              background 0.45s ease;
}

.acl-bar-fill--admin  { background: #4ade80; }
.acl-bar-fill--editor { background: #7dd3fc; }
.acl-bar-fill--mod    { background: #c084fc; }
.acl-bar-fill--member { background: rgba(161,161,170,0.5); }
.acl-bar-fill--viewer { background: rgba(113,113,122,0.35); }

/* ── Level text ──────────────────────────────────────────────────────────── */

.acl-level {
  font-family: ui-monospace, monospace;
  font-size: 0.4375rem;
  letter-spacing: 0.04em;
  color: #a1a1aa;
  white-space: nowrap;
  text-align: right;
  justify-self: end;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  transition: color 0.35s ease;
}

.acl-level--admin  { color: #4ade80; }
.acl-level--editor { color: #7dd3fc; }
.acl-level--mod    { color: #c084fc; }

/* ── Cursor ───────────────────────────────────────────────────────────────── */

.acl-cursor {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
  z-index: 10;
  /* CSS transition drives the smooth travel between pills */
  transition: transform 0.65s cubic-bezier(0.4, 0, 0.2, 1),
              opacity 0.25s ease;
  will-change: transform;
  opacity: 1;
}

.acl-cursor--hidden {
  opacity: 0;
  transition: opacity 0.25s ease;
}

.acl-cursor-icon {
  display: block;
  transform-origin: 1.5px 1px; /* tip of the arrow */
}

.acl-cursor-icon--click {
  animation: acl-cursor-click 0.28s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ── Keyframes ────────────────────────────────────────────────────────────── */

@keyframes acl-cursor-click {
  0%   { transform: scale(1);    }
  40%  { transform: scale(0.7);  }
  100% { transform: scale(1);    }
}

@keyframes acl-row-flash {
  0%   { background: rgba(255,255,255,0.04); }
  100% { background: transparent; }
}

@media (prefers-reduced-motion: reduce) {
  .acl-tr--flash            { animation: none; }
  .acl-cursor               { transition: none; }
  .acl-cursor-icon--click   { animation: none; }
  .acl-role-pill            { transition: none; }
  .acl-bar-fill             { transition: none; }
  .acl-level                { transition: none; }
}


/* ── Light mode ──────────────────────────────────────────────────────────── */

.acl-root:not(:is(.dark *)) {
  background: transparent;
}

/* integrations-illustration — themed like analytics-illustration (Vercel-style panel) */

/* ── Root ─────────────────────────────────────────────────────────────────── */

.itg-root {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-height: 0;
  flex: 1 1 0%;
  overflow: hidden;
  background: #000000;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  padding: 0.875rem 0.875rem 0.75rem;
}

/* ── Floating window ──────────────────────────────────────────────────────── */

.itg-window {
  flex: 1 1 0%;
  min-height: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  background: #0a0a0a;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 0.5rem;
  overflow: hidden;
  box-shadow: 0 4px 32px rgba(0,0,0,0.8), 0 0 0 1px rgba(255,255,255,0.02) inset;
}

.itg-header,
.itg-row {
  display: grid;
  align-items: center;
  column-gap: 0.5rem;
  padding-left: 0.75rem;
  padding-right: 0.75rem;
  grid-template-columns:
    1.25rem
    3.25rem
    minmax(0, 1fr)
    minmax(4.75rem, 2fr)
    2.75rem
    0.5rem;
}

.itg-header {
  padding-top: 0.4rem;
  padding-bottom: 0.25rem;
  flex-shrink: 0;
}

.itg-header-label {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.4375rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #a1a1aa;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.itg-header-label--source {
  justify-self: start;
  text-align: left;
}

.itg-header-label--metric {
  justify-self: center;
  text-align: center;
}

.itg-header-label--window {
  justify-self: center;
  text-align: center;
}

.itg-header-label--value {
  justify-self: end;
  text-align: right;
}

.itg-header-label--status {
  justify-self: center;
}

.itg-header-skip {
  min-height: 1px;
}

/* ── Rows — fills remaining space ─────────────────────────────────────────── */

.itg-rows {
  flex: 1 1 0%;
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  padding: 0.3rem 0 0.75rem;
  min-height: 0;
}

/* ── Row ──────────────────────────────────────────────────────────────────── */

.itg-row {
  padding-top: 0.28rem;
  padding-bottom: 0.28rem;
}

.itg-row--flash {
  animation: itg-row-flash 0.55s ease-out;
}

/* ── Logos — no tile / button chrome ──────────────────────────────────────── */

.itg-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  justify-self: center;
  width: 1.25rem;
  height: 1.25rem;
}

.itg-logo-svg {
  width: 0.75rem;
  height: 0.75rem;
  display: block;
}

/* ── Integration name ─────────────────────────────────────────────────────── */

.itg-name {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.625rem;
  font-weight: 500;
  color: #fafafa;
  white-space: nowrap;
  min-width: 0;
  justify-self: start;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1;
}

/* ── Metric type label ───────────────────────────────────────────────────── */

.itg-col-label {
  min-width: 0;
  justify-self: center;
  text-align: center;
  font-family: ui-monospace, monospace;
  font-size: 0.5rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #a1a1aa;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1;
}

/* ── Mini area chart (SVG) — brand stroke colors unchanged in TSX ─────────── */

.itg-chart-wrap {
  min-width: 0;
  width: 100%;
  height: 1.375rem;
  justify-self: stretch;
  align-self: center;
}

.itg-chart {
  width: 100%;
  height: 100%;
  display: block;
}

.itg-chart-baseline {
  stroke: rgba(255, 255, 255, 0.05);
  stroke-width: 0.4;
}

.itg-chart-line {
  stroke-width: 1.35;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ── Live metric value ────────────────────────────────────────────────────── */

.itg-metric {
  font-family: ui-monospace, monospace;
  font-size: 0.6875rem;
  font-weight: 600;
  color: #a1a1aa;
  white-space: nowrap;
  min-width: 0;
  justify-self: end;
  text-align: right;
  letter-spacing: -0.01em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.itg-metric--flash-emerald {
  animation: itg-metric-flash-emerald 0.5s ease-out;
}

.itg-metric--flash-amber {
  animation: itg-metric-flash-amber 0.5s ease-out;
}

/* ── Status — green / amber to match value flash language ─────────────────── */

.itg-status {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  justify-self: center;
  min-width: 0;
}

.itg-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.itg-status-dot {
  display: block;
  width: 0.3125rem;
  height: 0.3125rem;
  border-radius: 9999px;
  flex-shrink: 0;
}

.itg-status-dot--on      { background: #4ade80; }
.itg-status-dot--syncing {
  background: #fbbf24;
  animation: itg-dot-blink 0.9s step-start infinite;
}

/* ── Keyframes ────────────────────────────────────────────────────────────── */

@keyframes itg-row-flash {
  0%   { background: rgba(255,255,255,0.04); }
  100% { background: transparent; }
}

@keyframes itg-metric-flash-emerald {
  0%   { color: #4ade80; }
  100% { color: #a1a1aa; }
}

@keyframes itg-metric-flash-amber {
  0%   { color: #fbbf24; }
  100% { color: #a1a1aa; }
}

@keyframes itg-dot-blink {
  0%,  45% { opacity: 1;   }
  55%, 100% { opacity: 0.2; }
}

/* ── Reduced motion ───────────────────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .itg-row--flash              { animation: none; }
  .itg-metric--flash-emerald,
  .itg-metric--flash-amber { animation: none; }
  .itg-status-dot--syncing     { animation: none; }
}

/* ── Light mode ──────────────────────────────────────────────────────────── */

.itg-root:not(:is(.dark *)) {
  background: transparent;
}

